  ('Нейросеть пересказала', 'Новый противник устраивает серию ограблений и провоцирует горожан на хаос; защитнику города приходится решать, насколько далеко можно зайти ради порядка.', 'Тёмный рыцарь', array['The Dark Knight']::text[], 'text', 300, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Новый преступник объявляет себя спасителем общества и начинает устранять людей, которых считает недостойными; расследование приводит к давнему знакомому главного героя.', 'Бэтмен: Под красным колпаком', array['Под красным колпаком','Batman: Under the Red Hood']::text[], 'text', 300, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'После долгого отсутствия защитник города возвращается к прежней деятельности, но сталкивается с новым врагом, который использует страх и разрушает привычные опоры общества.', 'Тёмный рыцарь: Возрождение легенды', array['The Dark Knight Rises']::text[], 'text', 400, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'В городе появляется преступник, который оставляет загадки и выбирает жертв среди влиятельных людей; расследование постепенно выводит защитника на коррупцию и семейные тайны.', 'Бэтмен', array['The Batman','Бэтмен (фильм, 2022)']::text[], 'text', 500, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Подросток сопровождает пожилого учёного в поездках по параллельным мирам, где научные эксперименты регулярно создают проблемы, которые приходится переживать всей семье.', 'Рик и Морти', array['Rick and Morty']::text[], 'text', 100, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
