  ('Нейросеть пересказала', 'Мужчина, не способный создавать новые воспоминания, пытается найти человека, виновного в смерти его жены, пользуясь заметками и изображениями на собственном теле.', 'Помни', array['Memento']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Человек, который не может заснуть, помогает местному полицейскому расследовать убийство в северном городе, где летом почти не наступает ночь.', 'Бессонница', array['Insomnia']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Группа людей пытается провести сложную операцию в городе, где направление времени для разных участников не совпадает; важным инструментом становится предмет, чьё движение обращено вспять.', 'Довод', array['Tenet']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Чтобы избежать семейного ужина, пожилой учёный превращает себя в овощ, после чего внучка помогает ему участвовать в международной операции.', 'Огурчик Рик', array['Pickle Rick']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Дедушка и внук сталкиваются с существами, которые появляются из воспоминаний и постепенно заполняют дом; отличить настоящих близких от подделок становится трудно.', 'Полный Рикал', array['Total Rickall']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Подросток получает устройство для многократной отмены неудачных решений, но начинает использовать его так часто, что последствия становятся всё серьёзнее.', 'Эпизод с чаном кислоты', array['The Vat of Acid Episode']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'После того как подросток выпивает любовное средство, его чувства распространяются на значительную часть населения, а попытка исправить положение приводит к ещё более странным превращениям.', 'Зелье Рика', array['Rick Potion #9']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
