  ('Русский рэп', 'Как называется альбом Тимати, выпущенный в 2009 году и включающий песни «Наедине» и «Одноклассница»?', 'The Boss', array['The Boss (2009)']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Сотрудники учреждения готовят праздничное мероприятие, а руководительница пытается добиться порядка и соблюдения плана. Появление энергичного ведущего меняет ход подготовки.', 'Карнавальная ночь', array['Карнавальная ночь (фильм)']::text[], 'text', 100, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Скромный служащий тайно присваивает чужие автомобили, чтобы помогать людям, пострадавшим от мошенничества. Следователь пытается установить, кто стоит за этими поездками.', 'Берегись автомобиля', array['Берегись автомобиля (фильм)']::text[], 'text', 100, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Молодой человек из состоятельной семьи увлекается талантливой актрисой. Их отношения осложняются тем, что её прежний поклонник не собирается отступать.', 'Жестокий романс', array['Жестокий романс (фильм)']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'На предприятии по ошибке выдают человеку крупный выигрышный билет. Он пытается воспользоваться удачей, но окружающие начинают вмешиваться в его планы.', 'Зигзаг удачи', array['Зигзаг удачи (фильм)']::text[], 'text', 200, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Подросток из народа мореходов вместо того, чтобы убить пойманное крылатое существо, освобождает его и устанавливает с ним связь. Это меняет отношения между жителями острова и животными.', 'Как приручить дракона', array['How to Train Your Dragon']::text[], 'text', 300, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Молодой вождь и его крылатый спутник отправляются на поиски людей, скрывающих множество представителей необычного вида. Там они встречают женщину, которая давно живёт среди этих существ.', 'Как приручить дракона 2', array['How to Train Your Dragon 2']::text[], 'text', 300, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Военный отправляется в прошлое, чтобы защитить женщину, но обнаруживает, что её детство и история будущего уже изменены. В его задачу вмешивается машина, которая давно находится рядом с ней.', 'Терминатор: Генезис', array['Terminator Genisys']::text[], 'text', 400, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
  ('Нейросеть пересказала', 'Женщина, пережившая нападение робота в прошлом, объединяется с молодой работницей и прибывшим из будущего бойцом. Им нужно защитить девушку, от которой зависит дальнейший ход событий.', 'Терминатор: Тёмные судьбы', array['Terminator: Dark Fate']::text[], 'text', 400, null, null, null, null, null, null, false, null, null, null, null, null, null, null, null, null, true),
